package com.ventas.service;
import com.ventas.repository.*;import com.ventas.security.AuthFailure;import com.ventas.security.AuthModels.Identity;import com.fasterxml.jackson.databind.ObjectMapper;
import java.awt.image.BufferedImage;import java.io.*;import java.time.*;import java.util.*;import java.util.function.Supplier;import javax.imageio.ImageIO;import org.junit.jupiter.api.*;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class ProductImageServiceTest {
 ProductImageRepository repo;SettingsRepository audit;BusinessTransactions tx;ProductImageService service;Identity actor;
 @BeforeEach void setup(){repo=mock(ProductImageRepository.class);audit=mock(SettingsRepository.class);tx=mock(BusinessTransactions.class);service=new ProductImageService(repo,audit,tx,new ObjectMapper().findAndRegisterModules());actor=new Identity(1,"admin","N","A","ADM",false,Set.of("PRO.GESTIONAR"),UUID.randomUUID(),OffsetDateTime.now().plusHours(1));when(tx.write(any(),anyString(),anyString(),any())).thenAnswer(i->((Supplier<?>)i.getArgument(3)).get());when(repo.get(7)).thenReturn(new ProductImageRepository.Metadata(7,null,null));}
 String image(String format,int w,int h)throws Exception{var b=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB),format,b);return Base64.getEncoder().encodeToString(b.toByteArray());}
 @Test void normalizedJpegIsBoundedAndDoesNotDistortAspect()throws Exception{for(String format:List.of("png","jpeg")){var bytes=service.normalize(image(format,40,20));assertThat(bytes.length).isLessThanOrEqualTo(65536);var img=ImageIO.read(new ByteArrayInputStream(bytes));assertThat(img.getWidth()).isEqualTo(320);assertThat(img.getHeight()).isEqualTo(320);assertThat(img.getRGB(0,0)&0xffffff).isEqualTo(0xffffff);}}
 @Test void rejectsSvgGifCorruptOversizedAndDecompressionDimensions()throws Exception{for(String s:List.of("not-base64!",Base64.getEncoder().encodeToString("<svg/>".getBytes()),image("gif",2,2),image("png",4097,1),Base64.getEncoder().encodeToString(new byte[2097153]))){assertThatThrownBy(()->service.normalize(s)).isInstanceOfSatisfying(AuthFailure.class,e->assertThat(e.status()).isEqualTo(400));}}
 @Test void staleVersionAndContradictoryChangeDoNotWrite()throws Exception{when(repo.get(7)).thenReturn(new ProductImageRepository.Metadata(7,"a".repeat(64),LocalDateTime.now()));assertThatThrownBy(()->service.save(actor,"test",7,new ProductImageService.Change(null,true,null))).isInstanceOfSatisfying(AuthFailure.class,e->assertThat(e.status()).isEqualTo(409));assertThatThrownBy(()->service.save(actor,"test",7,new ProductImageService.Change(image("png",2,2),true,null))).isInstanceOf(AuthFailure.class);verify(repo,never()).save(anyLong(),any(),any());}
 @Test void bytesAreExcludedFromAudit()throws Exception{String encoded=image("png",20,10);service.save(actor,"test",7,new ProductImageService.Change(encoded,false,null));verify(repo).save(eq(7L),argThat(bytes->bytes.length<=65536),matches("[0-9a-f]{64}"));verify(audit).audit(eq(1L),eq("PRO.IMAGEN"),eq("producto_imagen"),eq(7L),argThat(json->!json.contains(encoded)),argThat(json->!json.contains(encoded)));}
 @Test void vendorCannotWriteWithoutPermission(){var vendor=new Identity(2,"vendor","N","A","VEN",false,Set.of("PRO.VER"),UUID.randomUUID(),OffsetDateTime.now().plusHours(1));assertThatThrownBy(()->service.save(vendor,"test",7,new ProductImageService.Change(null,true,null))).isInstanceOfSatisfying(AuthFailure.class,e->assertThat(e.status()).isEqualTo(403));verifyNoInteractions(repo,tx);}
}
